create function private.sync_dynamic_families_v1() returns jsonb
language sql immutable security invoker set search_path='' as $function$
 select $sync_dynamic_families${"menu":["menu"],"price_list":["menu"],"news":["rss"],"sport_program":["fixtures","club-program","team-program","pool-program"],"sport_results":["results","club-results","team-results","pool-results"],"sport_standing":["standings"],"sport_period_standing":["period-standings"],"sport_match_of_the_day":["matchday"],"sport_next_match":["next-match"],"sport_cancellations":["cancellations"],"sport_dressing_rooms":["dressing-rooms","changing-rooms"],"sport_officials":["officials"],"sport_team":["team-info"],"sport_sponsor":["sponsors"],"sport_activities":["activities","agenda"],"sport_trainings":["training"],"sport_volunteers":["volunteers"],"sport_birthdays":["birthdays"],"sport_visitor_arrivals":["visitors","team-arrivals"],"sport_referee_arrivals":["referees"],"ledscores_live_match":["scoreboard","goal"]}$sync_dynamic_families$::jsonb
$function$;

create function private.assert_sync_dynamic_configuration_v1(p_tenant_id uuid,p_slide_type text,p_orientation text,p_config jsonb)
 returns void language plpgsql stable security definer set search_path='' as $$
declare seed jsonb:=p_config->'seed';
begin
 if p_config is null or pg_catalog.pg_column_size(p_config)>524288
  or not extensions.jsonb_matches_schema(private.sync_dynamic_configuration_schema_v1()::json,p_config)
  then raise exception 'Source dynamic configuration invalid' using errcode='23514';end if;
 if p_config->>'slideType' is distinct from p_slide_type or seed->>'orientation' is distinct from p_orientation
  or not exists(select 1 from jsonb_array_elements_text(private.sync_dynamic_families_v1()->p_slide_type)family where family=seed->>'family')
  or length(btrim(seed->>'name'))not between 2 and 120
  or seed->'rows'<>'[]'::jsonb or seed->'news'<>'[]'::jsonb or seed->'ownRowIndexes'<>'[]'::jsonb
  or seed?'home' or seed?'away' or seed?'match' or seed?'poll' or seed?'youtubeUrl' or seed->>'state'<>'ready'
  then raise exception 'Source dynamic scope or facts invalid' using errcode='23514';end if;
 -- Only real, checksum-bound tenant media can be supplied by an author. The
 -- existing canonical snapshot resolves global provider versions separately.
 perform private.assert_sync_slide_v1(p_tenant_id,seed);
end;$$;
create function private.validate_sync_dynamic_authoring_v1() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 if new.configuration_json?'syncConfiguration' then
  if new.configuration_json?'sitesConfiguration' then raise exception 'Source and Sites dynamic identities cannot be mixed' using errcode='23514';end if;
  perform private.assert_sync_dynamic_configuration_v1(new.tenant_id,new.slide_type,new.orientation,new.configuration_json->'syncConfiguration');
 end if;
 return new;
end;$$;
create trigger dynamic_slides_validate_sync_configuration before insert or update of configuration_json,slide_type,orientation
 on public.dynamic_slides for each row execute function private.validate_sync_dynamic_authoring_v1();
create trigger dynamic_slide_versions_validate_sync_configuration before insert or update of configuration_json,slide_type,orientation
 on public.dynamic_slide_versions for each row execute function private.validate_sync_dynamic_authoring_v1();

create or replace function private.json_has_sites_authoring_v1(p_value jsonb)returns boolean
language sql immutable security invoker set search_path='' as $$
 select coalesce(pg_catalog.jsonb_path_exists(p_value,'$.**.sitesPresentation'),false)
  or coalesce(pg_catalog.jsonb_path_exists(p_value,'$.**.sitesConfiguration'),false)
  or coalesce(pg_catalog.jsonb_path_exists(p_value,'$.**.syncPresentation'),false)
  or coalesce(pg_catalog.jsonb_path_exists(p_value,'$.**.syncConfiguration'),false)
  or coalesce(p_value->>'rendererVersion' in('sites-v11','sites-v17','sync-v1'),false)
$$;
revoke all on function private.sync_dynamic_configuration_schema_v1(),private.sync_dynamic_families_v1(),private.assert_sync_dynamic_configuration_v1(uuid,text,text,jsonb),private.validate_sync_dynamic_authoring_v1(),private.json_has_sites_authoring_v1(jsonb) from public,anon,authenticated,service_role;
